package com.iare.club.entity;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="payment_webhook_deliveries",uniqueConstraints=@UniqueConstraint(name="uk_payment_webhook_delivery",columnNames={"provider","delivery_id"}))
public class PaymentWebhookDelivery{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=40)private String provider;@Column(name="delivery_id",nullable=false,length=150)private String deliveryId;@Column(name="payment_reference",length=100)private String paymentReference;@Column(name="event_type",length=60)private String eventType;@Column(nullable=false)private boolean accepted;@Column(length=500)private String detail;@Column(name="received_at",nullable=false)private Instant receivedAt;protected PaymentWebhookDelivery(){}public PaymentWebhookDelivery(String p,String d,String r,String e,boolean a,String detail,Instant at){provider=p;deliveryId=d;paymentReference=r;eventType=e;accepted=a;this.detail=detail;receivedAt=at;}}
